                if i + 1 >= len(argv):
                    sys.stderr.write("error: a value is required for '--fix <FIX>' but none was supplied\n\nFor more information, try '--help'.\n")
                    raise SystemExit(2)
                val = argv[i+1]
                if val.startswith('-'):
                    sys.stderr.write(err_unexpected(val, prog))
                    raise SystemExit(2)
                i += 2
            else:
                val = arg.split('=', 1)[1]
                i += 1
            try:
                fix = parse_int_value(val, '--fix <FIX>', 64)
