                i += 1
            if val not in ('degree', 'radian', 'gradian'):
                msg = f"error: invalid value '{val}' for '--angle_unit <angle_unit>'\n  [possible values: degree, radian, gradian]\n"
                low = val.lower()
                if low in ('degree', 'radian', 'gradian'):
