        i += 1
    return prog, fix, base, angle, (positionals[0] if positionals else None)

def xdg_cache_home():
    return os.environ.get('XDG_CACHE_HOME') or os.path.join(os.environ.get('HOME', ''), '.cache')

def xdg_data_home():
    return os.environ.get('XDG_DATA_HOME') or os.path.join(os.environ.get('HOME', ''), '.local', 'share')

def run_repl(fix, base, angle):
    hist_path = os.path.join(xdg_data_home(), 'eva', 'history.txt')
    cache_path = os.path.join(xdg_cache_home(), 'eva', 'previous_ans.txt')
    if not os.path.exists(hist_path):
        print("No previous history.")
    prev = 0.0
    prev_available = False
    history_lines = []
    any_line = False
    interactive = sys.stdin.isatty()
    try:
        if interactive:
            while True:
                try:
                    line = input('> ')
                except EOFError:
                    break
                any_line = True
                prev, prev_available = handle_repl_line(line, fix, base, angle, prev, prev_available, history_lines)
        else:
            for line in sys.stdin:
                any_line = True
                line = line.rstrip('\n')
                if line.endswith('\r'):
                    line = line[:-1]
                prev, prev_available = handle_repl_line(line, fix, base, angle, prev, prev_available, history_lines)
    finally:
        os.makedirs(os.path.dirname(cache_path), exist_ok=True)
        # Fresh EOF writes a bare 0; after evaluations write with newline, as observed.
        with open(cache_path, 'w') as f:
            if any_line:
                f.write(format_prev(prev) + "\n")
            else:
                f.write("0")
        if history_lines:
            os.makedirs(os.path.dirname(hist_path), exist_ok=True)
            existing = []
            if os.path.exists(hist_path):
                try:
                    existing = open(hist_path).read().splitlines()
                except Exception:
                    existing = []
            body = []
            if existing:
                if existing[0] == '#V2':
                    body = existing[1:]
                else:
                    body = existing
            body.extend(history_lines)
            with open(hist_path, 'w') as f:
                f.write('#V2\n')
                for h in body:
                    f.write(h + '\n')
    return 0

def format_prev(v):
    # Rust's Display for the stored previous answer is compact; this is close enough.
    if math.isfinite(v) and float(v).is_integer():
        return str(int(v))
    return repr(float(v))

def handle_repl_line(line, fix, base, angle, prev, prev_available, history_lines):
    if line.strip() != '':
        history_lines.append(line)
    try:
        val = eval_expr(line, fix=fix, base=base, angle_unit=angle,
                        prev_value=prev, prev_available=prev_available)
        print(format_output(val, fix, base))
        return val, True
    except ExprHelp:
        # In command mode this goes to stderr with rc=1; in the REPL it is just printed.
        print(HELP_EXPR, end='')
        return prev, prev_available
    except EvaError as e:
        print(e.msg)
        return prev, prev_available

def main(argv=None):
    argv = argv or sys.argv
    try:
        prog, fix, base, angle, expr = parse_cli(argv)
    except SystemExit as e:
        return int(e.code) if isinstance(e.code, int) else 0
    if expr is None or expr == '':
        return run_repl(fix, base, angle)
    try:
        val = eval_expr(expr, fix=fix, base=base, angle_unit=angle,
                        prev_value=0.0, prev_available=True)
        print(format_output(val, fix, base))
        return 0
    except ExprHelp:
        sys.stderr.write(HELP_EXPR)
        return 1
    except EvaError as e:
        sys.stderr.write(e.msg + "\n")
        return 1

if __name__ == '__main__':
    sys.exit(main())
