#!/usr/bin/env python3
import math
import os
import sys
import time
from dataclasses import dataclass

VERSION = "eva 0.3.1"
MAX_VALUE_DISPLAY = "179769313486231570" + "0" * (309 - len("179769313486231570"))
TOO_LARGE = "Error: to large to process! Max value: " + MAX_VALUE_DISPLAY

HELP_EXPR = """Constants
      pi       e

Functions
     sin   round     cos    atan     sec    ceil     cot    log2    sqrt
     log     deg     tan     abs   floor    cosh     exp   log10    asec
    asin    sinh    exp2    tanh    acot     rad   nroot     csc    acsc

Operators
* - + % ^ ! /
"""

FUNC_ARITY = {
    "sin": 1, "cos": 1, "tan": 1, "csc": 1, "sec": 1, "cot": 1,
    "sinh": 1, "cosh": 1, "tanh": 1,
    "asin": 1, "acos": 1, "atan": 1, "acsc": 1, "asec": 1, "acot": 1,
    "ln": 1, "log2": 1, "log10": 1, "sqrt": 1, "ceil": 1, "floor": 1,
    "abs": 1, "exp": 1, "exp2": 1, "round": 1, "deg": 1, "rad": 1,
    "log": 2, "nroot": 2,
}
# Longest first for prefix checks like sinh before sin, log10 before log.
FUNC_NAMES_LONG = sorted(FUNC_ARITY, key=len, reverse=True)
DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

class EvaError(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg

class ExprHelp(Exception):
    pass

@dataclass
class Token:
    typ: str
    val: object = None

class Lexer:
    def __init__(self, text, prev_value=0.0, prev_available=True):
        self.orig = text
        self.text = ''.join(ch for ch in text if not ch.isspace())
        self.prev_value = prev_value
        self.prev_available = prev_available

    def lex(self):
        s = self.text
        if s == "help":
            raise ExprHelp()
        # Auto-balance missing closing parentheses, but reject extra closing ones.
        bal = 0
        for ch in s:
            if ch == '(':
                bal += 1
            elif ch == ')':
                bal -= 1
                if bal < 0:
                    raise EvaError("Syntax Error: Mismatched parentheses!")
        if bal > 0:
            s += ')' * bal
        raw = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isdigit() or c == '.':
                j = i
                while j < n and (s[j].isdigit() or s[j] == '.'):
                    j += 1
                lit = s[i:j]
                if lit == '.' or lit.count('.') > 1:
                    raw.append(Token('BAD'))
                else:
                    try:
                        raw.append(Token('NUM', float(lit)))
                    except Exception:
                        raw.append(Token('BAD'))
                i = j
                continue
            if c == '*':
                if i + 1 < n and s[i+1] == '*':
                    raw.append(Token('POW'))
                    i += 2
                else:
                    raw.append(Token('MUL'))
                    i += 1
                continue
            if c == '+': raw.append(Token('PLUS')); i += 1; continue
            if c == '-': raw.append(Token('MINUS')); i += 1; continue
            if c == '/': raw.append(Token('DIV')); i += 1; continue
            if c == '%': raw.append(Token('MOD')); i += 1; continue
            if c == '^': raw.append(Token('POW')); i += 1; continue
            if c == '!': raw.append(Token('FACT')); i += 1; continue
            if c == ',': raw.append(Token('COMMA')); i += 1; continue
            if c == '(':
                raw.append(Token('LPAREN')); i += 1; continue
            if c == ')':
                raw.append(Token('RPAREN')); i += 1; continue
            if c == '_':
                if not self.prev_available:
                    raise EvaError("Syntax Error: No previous answer!")
                raw.append(Token('NUM', self.prev_value))
                i += 1
                continue
            if c.isalpha():
                # If an alphanumeric name is immediately followed by '(' it is a function name,
                # even if it happens to be pi/e (pi(2) is an unknown function in the original).
                j = i
                while j < n and s[j].isalnum():
                    j += 1
                if j < n and s[j] == '(':
                    raw.append(Token('FUNC', s[i:j]))
                    i = j
                    continue
                # A known function name followed by a numeric suffix gives a friendly error.
                for fname in FUNC_NAMES_LONG:
                    if s.startswith(fname, i):
                        k = i + len(fname)
                        if k < n and (s[k].isdigit() or s[k] == '.'):
                            raise EvaError(f"Syntax Error: Function '{fname}' expected parentheses")
                if s.startswith('pi', i):
                    raw.append(Token('NUM', math.pi))
                    i += 2
                    continue
                if c == 'e':
                    raw.append(Token('NUM', math.e))
                    i += 1
                    continue
                # Unknown bare identifiers normally trickle through to a parser error.
                j = i
                while j < n and s[j].isalpha():
                    j += 1
                # If letters are followed by a digit, the lexer reports an unexpected character.
                if j < n and s[j].isdigit():
                    bad = s[i:min(n, j+1)]
                    raise EvaError(f"Syntax Error: Unexpected character '{bad}'")
                raw.append(Token('UNKNOWN', s[i:j]))
                i = j
                continue
            raise EvaError(f"Syntax Error: Unexpected token: '{c}'")
        return self._insert_implicit(raw)

    def _insert_implicit(self, toks):
        out = []
        for tok in toks:
            if out and self._needs_mul(out[-1], tok):
                out.append(Token('MUL'))
            out.append(tok)
        return out

    @staticmethod
    def _needs_mul(a, b):
        # The original is intentionally conservative.  It inserts useful cases like
        # 2pi, pi2, 2sin(30), 2(3), and (2)(3), but not (2)3 or pipi.
        if a.typ == 'NUM' and b.typ in ('FUNC', 'LPAREN', 'NUM'):
            return True
        if a.typ == 'RPAREN' and b.typ == 'LPAREN':
            return True
        return False

class Parser:
    def __init__(self, tokens, angle_unit='degree'):
        self.toks = tokens
        self.i = 0
        self.angle_unit = angle_unit

    def current(self):
        if self.i >= len(self.toks):
            return Token('EOF')
        return self.toks[self.i]

    def accept(self, typ):
        if self.current().typ == typ:
            t = self.current()
            self.i += 1
            return t
        return None

    def expect(self, typ):
        t = self.accept(typ)
        if t is None:
            raise EvaError("Parser Error: Too many operators, too few operands")
        return t

    def parse(self):
        if not self.toks:
            return 0.0
        val = self.parse_add()
        cur = self.current().typ
        if cur == 'EOF':
            return val
        if cur == 'RPAREN' or cur == 'COMMA':
            raise EvaError("Syntax Error: Mismatched parentheses!")
        raise EvaError("Parser Error: Too many operators, too few operands")

    def parse_add(self):
        val = self.parse_mul()
        while True:
            if self.accept('PLUS'):
                val = checked_op(val + self.parse_mul())
            elif self.accept('MINUS'):
                val = checked_op(val - self.parse_mul())
            else:
                break
        return val

    def parse_mul(self):
        val = self.parse_power()
        while True:
            if self.accept('MUL'):
                val = checked_op(val * self.parse_power())
            elif self.accept('DIV'):
                rhs = self.parse_power()
                if rhs == 0.0:
                    raise EvaError("Math Error: Divide by zero error!")
                val = checked_op(val / rhs)
            elif self.accept('MOD'):
                rhs = self.parse_power()
                if rhs == 0.0:
                    raise EvaError(TOO_LARGE)
                try:
                    val = checked_op(math.fmod(val, rhs))
                except Exception:
                    raise EvaError(TOO_LARGE)
            else:
                break
        return val

    def parse_power(self):
        val = self.parse_unary_postfix()
        if self.accept('POW'):
            rhs = self.parse_power()
            try:
                val = math.pow(val, rhs)
            except Exception:
                raise EvaError(TOO_LARGE)
            val = checked_op(val)
        return val

    def parse_unary_postfix(self):
        if self.accept('PLUS'):
            val = +self.parse_unary_postfix()
        elif self.accept('MINUS'):
            val = -self.parse_unary_postfix()
        else:
            val = self.parse_primary()
        while self.accept('FACT'):
            val = factorial(val)
        return val

    def parse_primary(self):
        tok = self.current()
        if tok.typ == 'NUM':
            self.i += 1
            return float(tok.val)
        if tok.typ == 'BAD' or tok.typ == 'UNKNOWN':
            self.i += 1
            raise EvaError("Parser Error: Too many operators, too few operands")
        if tok.typ == 'LPAREN':
            self.i += 1
            if self.current().typ == 'RPAREN':
                raise EvaError("Parser Error: Too many operators, too few operands")
            val = self.parse_add()
            if not self.accept('RPAREN'):
                if self.current().typ == 'COMMA':
                    raise EvaError("Parser Error: Too many operators, too few operands")
                raise EvaError("Syntax Error: Mismatched parentheses!")
            return val
        if tok.typ == 'FUNC':
            self.i += 1
            name = tok.val
            if name not in FUNC_ARITY:
                # Consume no further tokens; this mirrors the user-facing diagnostic.
                raise EvaError(f"Syntax Error: Unknown function '{name}'")
            if not self.accept('LPAREN'):
                raise EvaError(f"Syntax Error: Function '{name}' expected parentheses")
            args = []
            if self.current().typ != 'RPAREN':
                args.append(self.parse_add())
                while self.accept('COMMA'):
                    args.append(self.parse_add())
            if not self.accept('RPAREN'):
                raise EvaError("Syntax Error: Mismatched parentheses!")
            need = FUNC_ARITY[name]
            if len(args) < need:
                raise EvaError(f"Parser Error: To few arguments for function, need {need}")
            if len(args) > need:
                raise EvaError("Parser Error: Too many operators, too few operands")
            return apply_func(name, args, self.angle_unit)
        raise EvaError("Parser Error: Too many operators, too few operands")

def checked_op(v):
    if not math.isfinite(v):
        raise EvaError(TOO_LARGE)
    return v

def domain_check(v):
    if not math.isfinite(v):
        raise EvaError("Domain Error: Out of bounds!")
    return v

def to_radians_arg(x, angle_unit):
    if angle_unit == 'radian':
        return x
    # The shipped program accepts gradian but treats it like degree for trig input.
    return math.radians(x)

def apply_func(name, args, angle_unit):
    x = args[0]
    try:
        if name == 'sin': return domain_check(math.sin(to_radians_arg(x, angle_unit)))
        if name == 'cos': return domain_check(math.cos(to_radians_arg(x, angle_unit)))
        if name == 'tan': return domain_check(math.tan(to_radians_arg(x, angle_unit)))
        if name == 'csc':
            s = math.sin(to_radians_arg(x, angle_unit))
            if s == 0.0: raise EvaError("Domain Error: Out of bounds!")
            return domain_check(1.0 / s)
        if name == 'sec':
            c = math.cos(to_radians_arg(x, angle_unit))
            if c == 0.0: raise EvaError("Domain Error: Out of bounds!")
            return domain_check(1.0 / c)
        if name == 'cot':
            t = math.tan(to_radians_arg(x, angle_unit))
            if t == 0.0: raise EvaError("Domain Error: Out of bounds!")
            return domain_check(1.0 / t)
        if name == 'sinh': return domain_check(math.sinh(x))
        if name == 'cosh': return domain_check(math.cosh(x))
        if name == 'tanh': return domain_check(math.tanh(x))
        if name == 'asin': return domain_check(math.asin(x))
        if name == 'acos': return domain_check(math.acos(x))
        if name == 'atan': return domain_check(math.atan(x))
        if name == 'acsc':
            if x == 0.0: raise EvaError("Domain Error: Out of bounds!")
            return domain_check(math.asin(1.0 / x))
        if name == 'asec':
            if x == 0.0: raise EvaError("Domain Error: Out of bounds!")
            return domain_check(math.acos(1.0 / x))
        if name == 'acot':
            if x == 0.0:
                return math.pi / 2.0
            return domain_check(math.atan(1.0 / x))
        if name == 'ln':
            if x <= 0.0: raise EvaError("Domain Error: Out of bounds!")
            return domain_check(math.log(x))
        if name == 'log2':
            if x <= 0.0: raise EvaError("Domain Error: Out of bounds!")
            return domain_check(math.log2(x))
        if name == 'log10':
            if x <= 0.0: raise EvaError("Domain Error: Out of bounds!")
            return domain_check(math.log10(x))
        if name == 'sqrt':
            if x < 0.0: raise EvaError("Domain Error: Out of bounds!")
            return domain_check(math.sqrt(x))
        if name == 'ceil': return float(math.ceil(x))
        if name == 'floor': return float(math.floor(x))
        if name == 'abs': return abs(x)
        if name == 'exp': return domain_check(math.exp(x))
        if name == 'exp2': return domain_check(math.pow(2.0, x))
        if name == 'round': return rust_round(x)
        if name == 'deg': return math.degrees(x)
        if name == 'rad': return math.radians(x)
        if name == 'log':
            b = args[1]
            if x <= 0.0 or b < 0.0 or b == 1.0:
                raise EvaError("Domain Error: Out of bounds!")
            if b == 0.0:
                denom = float('-inf')
            else:
                denom = math.log(b)
            return domain_check(math.log(x) / denom)
        if name == 'nroot':
            n = args[1]
            if x < 0.0:
                raise EvaError("Domain Error: Out of bounds!")
            if n == 0.0:
                if x == 0.0: return 0.0
                if x == 1.0: return 1.0
                raise EvaError("Domain Error: Out of bounds!")
            return domain_check(math.pow(x, 1.0 / n))
    except EvaError:
        raise
    except Exception:
        raise EvaError("Domain Error: Out of bounds!")
    raise EvaError(f"Syntax Error: Unknown function '{name}'")

def rust_round(x):
    if x >= 0:
        return float(math.floor(x + 0.5))
    return float(math.ceil(x - 0.5))

def factorial(x):
    if not math.isfinite(x) or x < 0.0 or not float(x).is_integer():
        raise EvaError("Domain Error: Out of bounds!")
    n = int(x)
    if n > 170:
        raise EvaError(TOO_LARGE)
    acc = 1.0
    for k in range(2, n + 1):
        acc *= k
    if not math.isfinite(acc):
        raise EvaError(TOO_LARGE)
    return acc

def eval_expr(text, fix=10, base=10, angle_unit='degree', prev_value=0.0, prev_available=True):
    lexer = Lexer(text, prev_value=prev_value, prev_available=prev_available)
    tokens = lexer.lex()
    parser = Parser(tokens, angle_unit=angle_unit)
    return parser.parse()

def group_every_three(s):
    groups = []
    while s:
        groups.append(s[-3:])
        s = s[:-3]
    return ','.join(reversed(groups)) if groups else ''

def format_output(value, fix=10, base=10):
    if base == 10:
        try:
            return f"{value:,.{fix}f}"
        except Exception:
            return str(value)
    return format_base(value, base, fix)

def format_base(value, base, fix):
    # The original first formats to decimal fixed precision, then converts that value.
    try:
        rounded = float(f"{value:.{fix}f}")
    except Exception:
        return str(value)
    neg = math.copysign(1.0, rounded) < 0
    a = abs(rounded)
    if math.isinf(a) or math.isnan(a):
        return str(rounded)
    int_part = int(a)
    frac = a - int_part
    if base == 1 and int_part != 0:
        # Matches the observed non-terminating radix-1 integer conversion.
        while True:
            time.sleep(3600)
    if int_part == 0:
        int_s = '0'
    else:
        digs = []
        n = int_part
        while n:
            d = n % base
            digs.append(DIGITS[d])
            n //= base
        int_s = ''.join(reversed(digs))
    if neg:
        int_s = '-' + int_s
    if frac == 0.0:
        frac_s = '0'
    else:
        digs = []
        for _ in range(fix):
            frac *= base
            d = int(frac)
            if d < 0 or d >= len(DIGITS):
                d = max(0, min(d, len(DIGITS)-1))
            digs.append(DIGITS[d])
            frac -= d
            if frac == 0.0:
                break
        frac_s = ''.join(digs) if digs else '0'
    padded = f"{int_s:>10}"
    return group_every_three(padded) + '.' + frac_s

# -------------------------- command-line interface -------------------------

def usage_line(prog):
    return f"Usage: {prog} [OPTIONS] [INPUT]"

def help_text(prog):
    return f"""Calculator REPL similar to bc(1)

Usage: {prog} [OPTIONS] [INPUT]

Arguments:
  [INPUT]  Optional expression string to run eva in command mode

Options:
  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]
  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]
  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]
  -h, --help                     Print help
  -V, --version                  Print version
"""

def err_unexpected(arg, prog, similar_arg=None):
    msg = f"error: unexpected argument '{arg}' found\n\n"
    if similar_arg:
        msg += f"  tip: a similar argument exists: '{similar_arg}'\n\n"
    elif arg.startswith('-'):
        msg += f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n"
    msg += usage_line(prog) + "\n\nFor more information, try '--help'.\n"
    return msg

def parse_int_value(val, opt_display, rng_hi):
    # clap accepts a leading '+', but not '-'.
    s = val
    if s.startswith('+'):
        s_num = s[1:]
    else:
        s_num = s
    if not s_num.isdigit():
        raise ValueError(f"error: invalid value '{val}' for '{opt_display}': invalid digit found in string\n\nFor more information, try '--help'.\n")
    if len(s_num) > 20:
        raise ValueError(f"error: invalid value '{val}' for '{opt_display}': number too large to fit in target type\n\nFor more information, try '--help'.\n")
    num = int(s_num)
    if num < 1 or num > rng_hi:
        raise ValueError(f"error: invalid value '{val}' for '{opt_display}': {num} is not in 1..={rng_hi}\n\nFor more information, try '--help'.\n")
    return num

def parse_cli(argv):
    prog = os.path.basename(argv[0]) if argv else 'executable'
    fix = 10
    base = 10
    angle = 'degree'
    positionals = []
    after_dd = False
    i = 1
    while i < len(argv):
        arg = argv[i]
        if not after_dd and arg == '--':
            after_dd = True
            i += 1
            continue
        if not after_dd and arg in ('-h', '--help'):
            print(help_text(prog), end='')
            raise SystemExit(0)
        if not after_dd and arg in ('-V', '--version'):
            print(VERSION)
            raise SystemExit(0)
        if not after_dd and (arg == '--fix' or arg.startswith('--fix=')):
            if arg == '--fix':
                if i + 1 >= len(argv):
                    sys.stderr.write("error: a value is required for '--fix <FIX>' but none was supplied\n\nFor more information, try '--help'.\n")
                    raise SystemExit(2)
                val = argv[i+1]
                if val.startswith('-'):
                    sys.stderr.write(err_unexpected(val, prog))
                    raise SystemExit(2)
                i += 2
            else:
                val = arg.split('=', 1)[1]
                i += 1
            try:
                fix = parse_int_value(val, '--fix <FIX>', 64)
            except ValueError as e:
                sys.stderr.write(str(e)); raise SystemExit(2)
            continue
        if not after_dd and (arg == '--base' or arg.startswith('--base=')):
            if arg == '--base':
                if i + 1 >= len(argv):
                    sys.stderr.write("error: a value is required for '--base <RADIX>' but none was supplied\n\nFor more information, try '--help'.\n")
                    raise SystemExit(2)
                val = argv[i+1]
                if val.startswith('-'):
                    sys.stderr.write(err_unexpected(val, prog))
                    raise SystemExit(2)
                i += 2
            else:
                val = arg.split('=', 1)[1]
                i += 1
            try:
                base = parse_int_value(val, '--base <RADIX>', 36)
            except ValueError as e:
                sys.stderr.write(str(e)); raise SystemExit(2)
            continue
        if not after_dd and (arg == '--angle_unit' or arg.startswith('--angle_unit=')):
            if arg == '--angle_unit':
                if i + 1 >= len(argv):
                    sys.stderr.write("error: a value is required for '--angle_unit <angle_unit>' but none was supplied\n  [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.\n")
                    raise SystemExit(2)
                val = argv[i+1]
                if val.startswith('-'):
                    sys.stderr.write(err_unexpected(val, prog))
                    raise SystemExit(2)
                i += 2
            else:
                val = arg.split('=', 1)[1]
                i += 1
            if val not in ('degree', 'radian', 'gradian'):
                msg = f"error: invalid value '{val}' for '--angle_unit <angle_unit>'\n  [possible values: degree, radian, gradian]\n"
                low = val.lower()
                if low in ('degree', 'radian', 'gradian'):
                    msg += f"\n  tip: a similar value exists: '{low}'\n"
                elif val == 'degreee':
                    msg += "\n  tip: a similar value exists: 'degree'\n"
                msg += "\nFor more information, try '--help'.\n"
                sys.stderr.write(msg)
                raise SystemExit(2)
            angle = val
            continue
        if not after_dd and arg.startswith('-f') and arg != '-f':
            val = arg[2:]
            if val.startswith('='):
                val = val[1:]
            try:
                fix = parse_int_value(val, '--fix <FIX>', 64)
            except ValueError as e:
                sys.stderr.write(str(e)); raise SystemExit(2)
            i += 1
            continue
        if not after_dd and arg == '-f':
            if i + 1 >= len(argv):
                sys.stderr.write("error: a value is required for '--fix <FIX>' but none was supplied\n\nFor more information, try '--help'.\n")
                raise SystemExit(2)
            val = argv[i+1]
            if val.startswith('-'):
                sys.stderr.write(err_unexpected(val, prog)); raise SystemExit(2)
            try:
                fix = parse_int_value(val, '--fix <FIX>', 64)
            except ValueError as e:
                sys.stderr.write(str(e)); raise SystemExit(2)
            i += 2
            continue
        if not after_dd and arg.startswith('-b') and arg != '-b':
            val = arg[2:]
            if val.startswith('='):
                val = val[1:]
            try:
                base = parse_int_value(val, '--base <RADIX>', 36)
            except ValueError as e:
                sys.stderr.write(str(e)); raise SystemExit(2)
            i += 1
            continue
        if not after_dd and arg == '-b':
            if i + 1 >= len(argv):
                sys.stderr.write("error: a value is required for '--base <RADIX>' but none was supplied\n\nFor more information, try '--help'.\n")
                raise SystemExit(2)
            val = argv[i+1]
            if val.startswith('-'):
                sys.stderr.write(err_unexpected(val, prog)); raise SystemExit(2)
            try:
                base = parse_int_value(val, '--base <RADIX>', 36)
            except ValueError as e:
                sys.stderr.write(str(e)); raise SystemExit(2)
            i += 2
            continue
        if not after_dd and arg.startswith('-a') and arg != '-a':
            val = arg[2:]
            if val.startswith('='):
                val = val[1:]
            if val not in ('degree', 'radian', 'gradian'):
                sys.stderr.write(f"error: invalid value '{val}' for '--angle_unit <angle_unit>'\n  [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.\n")
                raise SystemExit(2)
            angle = val
            i += 1
            continue
        if not after_dd and arg == '-a':
            if i + 1 >= len(argv):
                sys.stderr.write("error: a value is required for '--angle_unit <angle_unit>' but none was supplied\n  [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.\n")
                raise SystemExit(2)
            val = argv[i+1]
            if val.startswith('-'):
                sys.stderr.write(err_unexpected(val, prog)); raise SystemExit(2)
            if val not in ('degree', 'radian', 'gradian'):
                sys.stderr.write(f"error: invalid value '{val}' for '--angle_unit <angle_unit>'\n  [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.\n")
                raise SystemExit(2)
            angle = val
            i += 2
            continue
        if not after_dd and arg == '--angle-unit':
            sys.stderr.write(err_unexpected(arg, prog, '--angle_unit'))
            raise SystemExit(2)
        if not after_dd and arg.startswith('-'):
            sys.stderr.write(err_unexpected(arg, prog))
            raise SystemExit(2)
        positionals.append(arg)
        if len(positionals) > 1:
            sys.stderr.write(err_unexpected(arg, prog))
            raise SystemExit(2)
        i += 1
    return prog, fix, base, angle, (positionals[0] if positionals else None)

def xdg_cache_home():
    return os.environ.get('XDG_CACHE_HOME') or os.path.join(os.environ.get('HOME', ''), '.cache')

def xdg_data_home():
    return os.environ.get('XDG_DATA_HOME') or os.path.join(os.environ.get('HOME', ''), '.local', 'share')

def run_repl(fix, base, angle):
    hist_path = os.path.join(xdg_data_home(), 'eva', 'history.txt')
    cache_path = os.path.join(xdg_cache_home(), 'eva', 'previous_ans.txt')
    if not os.path.exists(hist_path):
        print("No previous history.")
    prev = 0.0
    prev_available = False
    history_lines = []
    any_line = False
    interactive = sys.stdin.isatty()
    try:
        if interactive:
            while True:
                try:
                    line = input('> ')
                except EOFError:
                    break
                any_line = True
                prev, prev_available = handle_repl_line(line, fix, base, angle, prev, prev_available, history_lines)
        else:
            for line in sys.stdin:
                any_line = True
                line = line.rstrip('\n')
                if line.endswith('\r'):
                    line = line[:-1]
                prev, prev_available = handle_repl_line(line, fix, base, angle, prev, prev_available, history_lines)
    finally:
        os.makedirs(os.path.dirname(cache_path), exist_ok=True)
        # Fresh EOF writes a bare 0; after evaluations write with newline, as observed.
        with open(cache_path, 'w') as f:
            if any_line:
                f.write(format_prev(prev) + "\n")
            else:
                f.write("0")
        if history_lines:
            os.makedirs(os.path.dirname(hist_path), exist_ok=True)
            existing = []
            if os.path.exists(hist_path):
                try:
                    existing = open(hist_path).read().splitlines()
                except Exception:
                    existing = []
            body = []
            if existing:
                if existing[0] == '#V2':
                    body = existing[1:]
                else:
                    body = existing
            body.extend(history_lines)
            with open(hist_path, 'w') as f:
                f.write('#V2\n')
                for h in body:
                    f.write(h + '\n')
    return 0

def format_prev(v):
    # Rust's Display for the stored previous answer is compact; this is close enough.
    if math.isfinite(v) and float(v).is_integer():
        return str(int(v))
    return repr(float(v))

def handle_repl_line(line, fix, base, angle, prev, prev_available, history_lines):
    if line.strip() != '':
        history_lines.append(line)
    try:
        val = eval_expr(line, fix=fix, base=base, angle_unit=angle,
                        prev_value=prev, prev_available=prev_available)
        print(format_output(val, fix, base))
        return val, True
    except ExprHelp:
        # In command mode this goes to stderr with rc=1; in the REPL it is just printed.
        print(HELP_EXPR, end='')
        return prev, prev_available
    except EvaError as e:
        print(e.msg)
        return prev, prev_available

def main(argv=None):
    argv = argv or sys.argv
    try:
        prog, fix, base, angle, expr = parse_cli(argv)
    except SystemExit as e:
        return int(e.code) if isinstance(e.code, int) else 0
    if expr is None or expr == '':
        return run_repl(fix, base, angle)
    try:
        val = eval_expr(expr, fix=fix, base=base, angle_unit=angle,
                        prev_value=0.0, prev_available=True)
        print(format_output(val, fix, base))
        return 0
    except ExprHelp:
        sys.stderr.write(HELP_EXPR)
        return 1
    except EvaError as e:
        sys.stderr.write(e.msg + "\n")
        return 1

if __name__ == '__main__':
    sys.exit(main())
